// Some portions generated by Codex
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { createScriptHarness } = require('./script-harness.js');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');

const scripts = require('./workbench-scripts.js').compiledScriptsDir();

function setup() {
    const requests = [];
    const harness = createScriptHarness({
        href: 'http://localhost/workbench/repositories/native/query',
        workbench: { resultFullscreen: { currentTarget() { return null; } } },
        ajaxHandler(options) {
            const callbacks = {};
            const xhr = {
                done(fn) { callbacks.done = fn; return xhr; },
                fail(fn) { callbacks.fail = fn; return xhr; },
                abort() { if (callbacks.fail) callbacks.fail(xhr, 'abort'); }
            };
            requests.push({ options, resolve(value) { callbacks.done(value); },
                reject() { callbacks.fail(xhr, 'error'); } });
            return xhr;
        }
    });
    const field = harness.registerElement('div', { id: 'lmdb-forced-strategy-field', hidden: true });
    const select = harness.registerElement('select', { id: 'lmdb-forced-strategy', name: 'lmdb-forced-strategy' });
    // Extend this fixture's jQuery instances with the ordinary data/each APIs used by catalogue loading.
    const data = new WeakMap();
    const jqueryPrototype = Object.getPrototypeOf(harness.$(select));
    jqueryPrototype.data = function(name, value) {
        const element = this.get(0);
        if (value === undefined) return (data.get(element) || {})[name];
        data.set(element, Object.assign({}, data.get(element), { [name]: value }));
        return this;
    };
    harness.$.each = (values, callback) => values.forEach((value, index) => callback(index, value));
    field.appendChild(select);
    harness.document.body.appendChild(field);
    harness.document.cookie = 'lmdb-forced-strategy=irKernel';
    harness.runScript('scripts/query.js');
    return { harness, query: harness.workbench.query, requests, field, select };
}

const available = { available: true, strategies: [{ name: 'irKernel', description: 'Compiled kernel' }] };

test('strategy selector stays empty and disabled until an available repository catalogue arrives', () => {
    const { query, requests, field, select } = setup();
    query.initializeLmdbForcedStrategy();
    assert.equal(field.hidden, true);
    assert.equal(select.disabled, true);
    assert.equal(select.value, '');
    requests[0].resolve(available);
    assert.equal(field.hidden, false);
    assert.equal(select.disabled, false);
    assert.equal(select.value, 'irKernel');
});

test('empty, unsupported and failed discoveries clear stale forcing and keep it disabled', () => {
    for (const response of [{ available: false, strategies: available.strategies },
        { available: true, strategies: [] }, null]) {
        const { query, requests, field, select } = setup();
        query.initializeLmdbForcedStrategy();
        if (response) requests[0].resolve(response); else requests[0].reject();
        assert.equal(field.hidden, true);
        assert.equal(select.disabled, true);
        assert.equal(select.value, '');
    }
});

test('late discoveries cannot re-enable a disposed page or override a newer request', () => {
    const { query, requests, field, select } = setup();
    query.initializeLmdbForcedStrategy();
    query.loadLmdbForceableStrategies();
    requests[1].resolve({ available: false, strategies: [] });
    requests[0].resolve(available);
    assert.equal(field.hidden, true);
    assert.equal(select.disabled, true);
    query.loadLmdbForceableStrategies();
    query.resetState('navigate');
    requests[2].resolve(available);
    assert.equal(field.hidden, true);
    assert.equal(select.disabled, true);
});

test('query template starts hidden and disabled and has no process-property controls', () => {
    const workbench = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ URLSearchParams, window: { location: { search: '' } }, workbench });
    const script = path.join(scripts, 'workbenchViews.js');
    vm.runInContext(fs.readFileSync(script, 'utf8'), context);
    const templates = [];
    const runtime = { nothing: null, html(strings, ...values) {
        const result = { strings: Array.from(strings), values };
        templates.push(result);
        return result;
    }, render() {} };
    context.workbench.views.pageTemplate({ viewId: 'query', vars: [], rows: [], metadata: {} },
        { basePath: '/workbench', repositoryId: 'native', workbench: {} }, runtime);
    const markup = templates.map(template => template.strings.join('')).join('');
    assert.match(markup, /id="lmdb-forced-strategy-field"[^>]*\bhidden/);
    assert.match(markup, /id="lmdb-forced-strategy"[^>]*\bdisabled/);
    assert.doesNotMatch(markup, /lmdb-runtime-|Runtime features apply globally/);
});
